  {(mapaPublico.ambientes||[]).map(a=><span key={a.id} className="absolute z-10 hidden sm:block text-[9px] sm:text-xs bg-amber-950/90 border border-amber-600 rounded px-1 text-center pointer-events-none" style={{left:`${a.x}%`,top:`${a.y}%`,transform:'translate(-50%,-50%)'}}>{a.nome}</span>)}
